import{_ as a,o as t,c as i,a5 as o}from"./chunks/framework.DrDMl0tG.js";const g=JSON.parse('{"title":"Changelog: v2.7.0","description":"","frontmatter":{},"headers":[],"relativePath":"sections/changelog/v2.7.0.md","filePath":"sections/changelog/v2.7.0.md"}'),n={name:"sections/changelog/v2.7.0.md"};function r(s,e,l,d,c,h){return t(),i("div",null,[...e[0]||(e[0]=[o('<h1 id="changelog-v2-7-0" tabindex="-1">Changelog: v2.7.0 <a class="header-anchor" href="#changelog-v2-7-0" aria-label="Permalink to &quot;Changelog: v2.7.0&quot;">​</a></h1><h2 id="breaking-glm-vec4-orientations-are-w-x-y-z" tabindex="-1">Breaking: glm::vec4 orientations are (w, x, y, z) <a class="header-anchor" href="#breaking-glm-vec4-orientations-are-w-x-y-z" aria-label="Permalink to &quot;Breaking: glm::vec4 orientations are (w, x, y, z)&quot;">​</a></h2><p>rayrai&#39;s <code>glm::vec4</code> quaternions hold <code>(w, x, y, z)</code> in the vector&#39;s <code>x, y, z, w</code> components, as the headers always documented. The setters used to read the vector as <code>(x, y, z, w)</code> instead. That meant:</p><ul><li><code>getOrientation()</code> did not return what was set;</li><li>the documented identity <code>glm::vec4(1, 0, 0, 0)</code> turned objects 180° about x;</li><li>the vector and scalar <code>setOrientation</code> overloads disagreed.</li></ul><p>These now all use <code>(w, x, y, z)</code>:</p><ul><li><code>Visuals::setOrientation(const glm::vec4&amp;)</code>;</li><li><code>InstancedVisuals::addInstance(position, orientation, ...)</code>;</li><li><code>InstancedVisuals::InstanceSpec::orientation</code> (default <code>(1, 0, 0, 0)</code>);</li><li><code>InstancedVisuals::setOrientation(id, orientation)</code>;</li><li><code>tcp_viewer::ClientRequest::quat</code> (default <code>(1, 0, 0, 0)</code>).</li></ul><p>Code that passed <code>(x, y, z, w)</code> to work around the old behaviour must switch. The old identity <code>{0, 0, 0, 1}</code> is now a 180° turn about z.</p><p>The same fix applies to the TCP viewer:</p><ul><li>body frames of rotated bodies point the right way;</li><li><strong>Set GC</strong> no longer reorders a floating base&#39;s quaternion components, which used to turn an upright robot upside down.</li></ul><h2 id="rendering" tabindex="-1">Rendering <a class="header-anchor" href="#rendering" aria-label="Permalink to &quot;Rendering&quot;">​</a></h2><ul><li><strong>Glass.</strong> <code>Material::glass</code> and <code>RenderQualitySettings::geometryRefraction</code> trace refraction through glass geometry, progressively, with an adaptive mode. The backend is portable GPU tracing or, where available, Vulkan ray queries. See <a href="./../rayrai/Materials.html">PBR materials</a> and <a href="./../rayrai/RenderQuality.html">Render quality, tone mapping, color grading</a>.</li><li><strong>Foliage.</strong><ul><li>Per-instance LOD, draw batching, depth prepasses and occlusion.</li><li>An on-disk mesh-LOD cache and asynchronous mesh preparation.</li><li>BC7 texture storage and wind controls.</li><li>See <a href="./../rayrai/Visuals.html">Custom visuals, instancing, and scene helpers</a> and <a href="./../rayrai/Performance.html">Performance notes and the C++ API reference</a>.</li></ul></li><li><strong>Lighting.</strong> Sky-visibility and baked-irradiance grids, and directional soft shadows. See <a href="./../rayrai/Lighting.html">Lighting, shadows, and HDR/IBL</a>.</li><li><strong>Faster frames, identical images.</strong> Frame submission does less work: texture binding, uniform upload, shadow and primitive-batch buffers, render-target reuse. Rendered images are unchanged.</li></ul><h2 id="fixes" tabindex="-1">Fixes <a class="header-anchor" href="#fixes" aria-label="Permalink to &quot;Fixes&quot;">​</a></h2><ul><li><strong>Screen-space AO flicker.</strong> AO is now deterministic at sky silhouettes. Its screen-space derivatives were evaluated only on geometry pixels, which is undefined in a 2x2 quad that straddles the sky, and made AO flicker on Apple GPUs.</li><li><strong>Texture-unit rebinding.</strong> On GPUs with 16 or 32 fragment texture units, <code>Material::applyTo</code> no longer binds one texture unit twice when maps are relocated.</li><li><strong>Bound pixel-unpack buffers.</strong> Lazily uploaded cloud-noise and fallback textures no longer fail when the application leaves a <code>GL_PIXEL_UNPACK_BUFFER</code> bound.</li><li><strong>Instanced shaders on macOS.</strong> Instanced shaders no longer fetch vertex colour and tangent attributes that the specialized foliage variants do not use. Apple&#39;s compiler keeps unused vertex outputs.</li><li><strong>CoACD example startup.</strong> <code>rayrai_coacd_mesh_approximation</code> builds its collision parts before opening the window, and reports that a cold cache can take minutes.</li></ul>',13)])])}const p=a(n,[["render",r]]);export{g as __pageData,p as default};
